    {
      "card_ids": ["C05"],
      "claim": "Safinamide absolute oral bioavailability was about 95% (90% CI 90–99%) versus IV in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Isoniazid absolute oral bioavailability was 93% in fasting TB patients, supporting high F.",
      "evidence_role": "supportive"
