    {
      "card_ids": ["C38"],
      "claim": "Rufinamide absolute bioavailability was approximately 70–85% in pediatric and adult patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Ketanserin absolute bioavailability was 50.4% in healthy subjects, above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dabrafenib absolute oral bioavailability was 95% in humans under fasted conditions, supporting high F for a complex heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Alfuzosin absolute oral bioavailability was 64.5% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Zimelidine absolute bioavailability was 29% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Compound 2 had 47% oral bioavailability in a human microdose study, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Brequinar oral availability was greater than 100% versus IV in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Sulpiride mean oral bioavailability was about 35% in humans, above the 20% threshold despite wide interindividual variability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All ten high-transfer experimental analogues have absolute oral bioavailability estimates above 20% (range about 29% to >95%), with most in the 50–95% range; no retrieved evidence indicates F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule.",
    "No query-specific data on solubility, permeability, or first-pass metabolism are available.",
    "Some analogues show variable or lower F, but their central estimates remain above the 20% threshold."
  ],
